"""Prepare an offline, label-hidden listening/reference worksheet from private evaluation outputs."""
from pathlib import Path
import argparse,json,html,shutil,secrets

def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--results',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args()
 if a.output.exists():p.error('Choose a new output directory')
 report=json.loads(a.results.read_text());samples={r['sample']:r for r in report['results']};a.output.mkdir(parents=True);cards=[];mapping=[]
 for index,(identifier,row) in enumerate(samples.items(),1):
  shutil.copyfile(a.results.parent/(identifier+'.wav'),a.output/f'sample-{index}-reference.wav')
  conditions=['normalized','gtcrn-normalized'];secrets.SystemRandom().shuffle(conditions);radios=[]
  for label,condition in zip(['A','B'],conditions):
   filename=f'sample-{index}-{label}.wav';shutil.copyfile(a.results.parent/(identifier+'-'+condition+'.wav'),a.output/filename)
   ratings=''.join(f'<label>{metric}<select data-metric="{metric}" data-label="{label}"><option value="">Not rated</option>'+''.join(f'<option>{n}</option>' for n in range(1,6))+'</select></label>' for metric in ['clarity','noise_control','naturalness'])
   radios.append(f'<div><h3>Audio {label}</h3><audio controls preload="none" src="{filename}"></audio><div class="ratings">{ratings}</div></div>')
  cards.append(f'<section data-id="{html.escape(identifier)}"><h2>Sample {index} · {html.escape(identifier)}</h2><p>Source interval: {row["start"]:.1f}–{row["start"]+row["duration"]:.1f} seconds. Ratings: 1 = poor, 5 = excellent.</p><h3>Reference audio · unfiltered original</h3><audio controls preload="none" src="sample-{index}-reference.wav"></audio><div class="pair">'+''.join(radios)+'</div><label>Human reference: write exactly what you hear before reading any model transcript.<textarea rows="5" spellcheck="false"></textarea></label><label><input type="checkbox" class="reviewed"> I listened and manually corrected this reference.</label></section>')
  mapping.append({'id':identifier,'conditions':dict(zip(['A','B'],conditions))})
 config=json.dumps(mapping).replace('<','\\u003c')
 document='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Traccia · private listening review</title><style>body{font:16px system-ui;background:#faf8f4;color:#332e2a;max-width:1100px;margin:40px auto;padding:20px}section{background:white;padding:24px;border:1px solid #decebf;border-radius:16px;margin:24px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}audio,textarea{width:100%}textarea{box-sizing:border-box;font:inherit;margin:12px 0;padding:12px}.ratings{display:flex;gap:12px;flex-wrap:wrap}label{display:block}select{display:block;margin:6px 0}button{background:#a45438;color:white;border:0;border-radius:8px;padding:14px 20px;font:inherit}@media(max-width:650px){.pair{grid-template-columns:1fr}}</style><h1>Private listening and reference review</h1><p>This page works offline and sends nothing to a server. Audio A/B labels hide the preprocessing method in the worksheet. No model hypotheses are included. Listen at the same device volume; rate clarity, noise control and naturalness. Do not infer medical facts that are inaudible.</p><p>Your original recordings are unchanged. The worksheet is not autosaved: export your references before closing.</p>'''+''.join(cards)+'''<button id="export">Export private review JSON</button><script>const samples='''+config+''';document.getElementById('export').onclick=()=>{const output={samples:samples.map(sample=>{const section=[...document.querySelectorAll('section')].find(x=>x.dataset.id===sample.id);const reference=section.querySelector('textarea').value.trim();const reviewed=section.querySelector('.reviewed').checked;const ratings={A:{},B:{}};for(const el of section.querySelectorAll('[data-metric]'))ratings[el.dataset.label][el.dataset.metric]=el.value?Number(el.value):null;return {...sample,reference,reference_reviewed:reviewed&&Boolean(reference),ratings};})};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='private-human-review.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};</script></html>'''
 (a.output/'index.html').write_text(document);print(a.output/'index.html')
if __name__=='__main__':main()
